questions.answer:
function omit(object, ...keys) {
  let copy = { ...object };
  for (const key of keys) {
    const { [key]: removed, ...rest } = copy;
    copy = rest;
  }
  return copy;
}

const user = { name: 'Kakade', password: 'secret', role: 'admin' };
console.log(omit(user, 'password'));
console.log(user.password);

